import { Box, Stack, Typography } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { useBoundRunId, useRunSelector } from '../../../hooks/use_action_runs'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionRunHistoryOwner } from '../state/action_run_history_owner'
import { ActionRunStatusOwner } from '../state/action_run_status_owner'
import { ActionPromptOwner } from '../../agent/action_prompt_owner'
import { ActionAgentInteraction } from './action_agent_interaction'
import { ActionInputSplitter } from './action_input_splitter';
import { ActionLayoutSurface } from './action_layout_surface';
import { ActionPopupBottomRow } from './action_popup_bottom_row'
import type { ActionPopupRuntime } from './action_popup_types'
import { ActionRunDisabledMessage } from './action_run_disabled_message'

interface CommandActionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    baseContext: ActionContext
    readOnlyMessage: string | null
    runtime: ActionPopupRuntime
    showHistoricalHistory?: boolean
}

/** Command status, history, scheduling, and run controls. */
export function CommandAction(props: CommandActionProps) {
    const { action, assignmentContext, baseContext, readOnlyMessage, runtime, showHistoricalHistory } = props
    const {
        bindingStore, conversationStore, historyStore, inputStore, resultStore, runValidationError, scheduleStore,
        settingsStore, commandLayoutStore,
    } = runtime
    const boundRunId = useBoundRunId(bindingStore)
    const activeActionType = useRunSelector(boundRunId, (run) => run?.activeActionType ?? null)
    const sessionActive = useRunSelector(boundRunId, (run) => run?.status === 'queued'
        || run?.status === 'running'
        || run?.status === 'waitingForInput')
    const showBottomRow = sessionActive && activeActionType !== 'agent'

    if (readOnlyMessage) {
        return (
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                {showHistoricalHistory ? <ActionRunHistoryOwner store={historyStore} /> : null}
                <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
            </Stack>
        )
    }

    if (sessionActive && activeActionType === 'agent') {
        return <ActionAgentInteraction action={action} assignmentContext={assignmentContext} baseContext={baseContext} runtime={runtime} />;
    }

    return (
        <>
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                <ActionScheduleOwner action={action} context={baseContext} store={scheduleStore} />
                <ActionRunStatusOwner bindingStore={bindingStore} resultStore={resultStore} />
                <ActionRunDisabledMessage action={action} settingsStore={settingsStore} />
                {runValidationError ? (
                    <Typography color="error.main" role="alert" variant="caption">
                        {runValidationError}
                    </Typography>
                ) : null}
                <ActionLayoutSurface store={commandLayoutStore}>
                    {!sessionActive ? (
                        <ActionPromptOwner
                            action={action}
                            bindingStore={bindingStore}
                            context={assignmentContext}
                            conversationStore={conversationStore}
                            historyStore={historyStore}
                            inputStore={inputStore}
                            layoutStore={commandLayoutStore}
                            questionsEnabled={false}
                            resultStore={resultStore}
                            runValidationError={runValidationError}
                            scheduleStore={scheduleStore}
                            settingsStore={settingsStore}
                        />
                    ) : null}
                    {!sessionActive ? <ActionInputSplitter store={commandLayoutStore} /> : null}
                    <Box data-layout-adjacent aria-label="Command run history" sx={{ flex: 1, minHeight: 0, overflowY: 'auto' }}>
                        <ActionRunHistoryOwner store={historyStore} />
                    </Box>
                </ActionLayoutSurface>
            </Stack>
            {showBottomRow ? (
                <ActionPopupBottomRow
                    action={action}
                    assignmentContext={assignmentContext}
                    bindingStore={bindingStore}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    settingsStore={settingsStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                />
            ) : null}
        </>
    )
}

import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import type { PreparedActionPrompt } from '../../data/action_run_types'
import { isRemoteControlConnectionError } from '../data/remote_control_storage_service'
import { register } from '../service_injector'
import { MarkdownDraft, type MarkdownDraftBinding } from '../markdown/markdown_draft'

const DRAFT_KEY_SEPARATOR = String.fromCharCode(0)

export type ActionPromptPreparationStatus = 'failed' | 'loading' | 'ready'

interface ActionPromptDraftEditorSnapshot {
    preparationStatus: ActionPromptPreparationStatus
    replacementRevision: number
}

interface ActionPromptDraftOptions {
    initialValue?: string
    prepare: boolean
}

function promptDraftContextIdentity(context: ActionContext) {
    return context.cardInternalId ? `card${DRAFT_KEY_SEPARATOR}${context.cardInternalId}` : actionContextIdentity(context)
}

function promptDraftKey(actionId: string, context: ActionContext, conversationId: string | null) {
    return `${actionId}${DRAFT_KEY_SEPARATOR}${promptDraftContextIdentity(context)}${DRAFT_KEY_SEPARATOR}${conversationId ?? 'new'}`
}

/** Stable prompt state shared by editor and prompt-dependent leaf controls. */
export class ActionPromptDraft {
    private applyingExternalValue = false
    private diagramPath: string | null = null
    readonly editorDraft: MarkdownDraftBinding
    private editorSnapshot: ActionPromptDraftEditorSnapshot
    private locallyEdited = false
    readonly markdownDraft: MarkdownDraft
    private preparationRequired: boolean
    private preparationStarted = false
    private revision = 0

    constructor(initialValue: string, preparationRequired: boolean) {
        this.editorSnapshot = {
            preparationStatus: preparationRequired ? 'loading' : 'ready',
            replacementRevision: 0,
        }
        this.markdownDraft = new MarkdownDraft(initialValue)
        this.editorDraft = {
            addEventListener: (type, listener) => this.markdownDraft.addEventListener(type, listener),
            edit: this.handleEditorDraftEdit,
            getSnapshot: this.markdownDraft.getSnapshot,
            removeEventListener: (type, listener) => this.markdownDraft.removeEventListener(type, listener),
            subscribeEditor: this.markdownDraft.subscribeEditor,
        }
        this.markdownDraft.subscribe(this.handleMarkdownEdit)
        this.preparationRequired = preparationRequired
    }

    readonly getSnapshot = () => this.markdownDraft.getSnapshot()

    readonly getEditorSnapshot = () => this.editorSnapshot

    readonly requestInsertion = (markdown: string) => this.markdownDraft.requestInsertion(markdown)

    readonly subscribe = (listener: () => void) => this.markdownDraft.subscribe(listener)

    readonly subscribeEditor = (listener: () => void) => {
        this.markdownDraft.addEventListener('actionEditorChanged', listener)

        return () => this.markdownDraft.removeEventListener('actionEditorChanged', listener)
