    const source = ts.createSourceFile(path, content, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
    const endings = [];
    function collect(node) {
        if (ts.isImportDeclaration(node) || ts.isVariableStatement(node) || ts.isExpressionStatement(node)
            || ts.isReturnStatement(node) || ts.isPropertySignature(node)) {
            if (content[node.end - 1] "'!== '"';') endings.push(node.end);
        }
        ts.forEachChild(node, collect);
    }
    collect(source);
    let result = content;
    for (const position of endings.sort((first, second) => second - first)) {
        result = result.slice(0, position) + ';' + result.slice(position);
    }
    fs.writeFileSync(path, result);
}
